const D = { scale:1, density:.55, jets:3, hue:205, energy:.6, speed:1, x:.5, y:.82, tiers:3, night:.3, seed:0, style:'stone', act:'calm' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const fr = i => { const q = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q - Math.floor(q); };
const u = Math.min(width, height);
const st = P.style;
const hue = ((P.hue%360)+360)%360;
const bt = K.beat * P.speed;
const cx = P.x*width, base = P.y*height;
const sc = P.scale;
const tiers = Math.max(1, Math.min(4, Math.round(P.tiers)));
const njet = Math.max(1, Math.min(9, Math.round(P.jets)));

// smoothed audio
S.bass = (S.bass||0)*.82 + (A.bass||0)*.18;
S.rms  = (S.rms||0)*.85 + (A.rms||0)*.15;

// real-time dt (guard t0 resets)
if (S.lt == null || K.t < S.lt) S.lt = K.t;
let dt = K.t - S.lt; S.lt = K.t;
if (dt < 0 || dt > 0.2) dt = 1/60;

// palette per style
function pal(){
  const nt = P.night; // 0 day-cool .. 1 warm night lamp
  const lampH = 40 - nt*8, lampS = 30 + nt*55;
  if (st==='blueprint') return { air:[210,60,10], stone:[205,50,16], edge:[195,70,88], water:[195,80,80], foam:[195,40,95], lamp:[195,70,92], schem:true };
  if (st==='ink-wash')  return { air:[hue,8,12], stone:[hue,6,22], edge:[hue,5,55], water:[hue,12,50], foam:[hue,6,80], lamp:[hue,14,82], ink:true };
  if (st==='thermal')   return { air:[240,80,6], stone:[280,55,20], edge:[30,85,70], water:[205,85,65], foam:[190,70,92], lamp:[55,95,98], therm:true };
  if (st==='noir')      return { air:[hue,6,6], stone:[hue,5,14], edge:[hue,4,60], water:[hue,7,40], foam:[hue,4,88], lamp:[lampH,lampS,96], noir:true };
  // stone (default): carved limestone + translucent water
  return { air:[hue, 18, 9], stone:[hue+8,14,34], edge:[hue,10,60], water:[hue,55,72], foam:[(hue+8)%360,22,96], lamp:[lampH,lampS,98] };
}
const C = pal();

function tierGeom(i){ // i=0 bottom pool .. up
  const t = i/tiers;
  const w = u*sc*(0.62 - t*0.34);
  const y = base - i*u*sc*0.19;
  const h = u*sc*0.05*(1 - t*0.3);
  return { w, y, h };
}

// ---- cached carved stone base ----
const bkey = width+'x'+height+':'+st+':'+P.seed+':'+sc.toFixed(2)+':'+tiers+':'+P.x.toFixed(2)+':'+P.y.toFixed(2)+':'+P.night.toFixed(2);
if (!S.bg || S.bgKey !== bkey){
  S.bgKey = bkey;
  const g = (S.bg && S.bg.width===width && S.bg.height===height) ? S.bg : (S.bg = createGraphics(width,height));
  g.colorMode(HSB,360,100,100,100); g.clear(); g.push();
  g.noStroke();
  // faint pool of light on the ground under the fountain
  g.push(); g.drawingContext.globalAlpha = C.noir?0.5:0.32;
  for (let r=6;r>0;r--){ g.fill(C.lamp[0],C.lamp[1]*0.4,C.lamp[2], 5); g.ellipse(cx, base+u*sc*0.03, u*sc*(0.7)*(r/6)*2, u*sc*0.34*(r/6)); }
  g.pop();
  // carved column
  const colW = u*sc*0.06;
  const topY = tierGeom(tiers-1).y - u*sc*0.05;
  g.fill(C.stone[0],C.stone[1],C.stone[2]*0.9,100);
  g.rect(cx-colW/2, topY, colW, base-topY, colW*0.3);
  // raking-light highlight on column left, shadow right
  if (!C.schem){ g.fill(C.edge[0],C.edge[1],C.edge[2],26); g.rect(cx-colW/2, topY, colW*0.4, base-topY, colW*0.2);
    g.fill(C.air[0],C.air[1],C.air[2],40); g.rect(cx+colW*0.1, topY, colW*0.4, base-topY, colW*0.2); }
  // tiers (basins) bottom to top, carved lips with chiaroscuro
  for (let i=0;i<tiers;i++){
    const G = tierGeom(i);
    if (C.schem){ // blueprint: line-only schematic
      g.noFill(); g.stroke(C.edge[0],C.edge[1],C.edge[2],90); g.strokeWeight(Math.max(1,u*0.0016));
      g.ellipse(cx, G.y, G.w, G.w*0.34);
      g.ellipse(cx, G.y+G.h, G.w*0.94, G.w*0.32);
      g.line(cx-G.w/2, G.y, cx-G.w*0.47, G.y+G.h);
      g.line(cx+G.w/2, G.y, cx+G.w*0.47, G.y+G.h);
      // dimension ticks
      for (let k=0;k<7;k++){ const a=k/6*Math.PI - Math.PI; g.point(cx+Math.cos(a)*G.w/2, G.y+Math.sin(a)*G.w*0.17); }
      g.noStroke();
      continue;
    }
    // bowl underside (shadow)
    g.fill(C.stone[0],C.stone[1]*1.1,C.stone[2]*0.55,100);
    g.ellipse(cx, G.y+G.h*1.1, G.w*0.96, G.w*0.3);
    // bowl body
    for (let s=0;s<5;s++){ const t=s/4; g.fill(C.stone[0],C.stone[1]*(1-t*0.3), C.stone[2]*(0.7+t*0.5), 100);
      g.arc(cx, G.y+G.h*0.5, G.w*(0.98-t*0.02), (G.w*0.34+G.h)*(0.98-t*0.02), 0, Math.PI); }
    // rim lip
    g.fill(C.stone[0],C.stone[1]*0.8,C.stone[2]*1.25,100);
    g.ellipse(cx, G.y, G.w, G.w*0.34);
    // inner shadow (water well)
    g.fill(C.water[0],C.water[1],C.water[2]*(C.ink?0.9:0.55), C.ink?55:80);
    g.ellipse(cx, G.y, G.w*0.8, G.w*0.27);
    // ink dry-brush edge speckle
    if (C.ink){ for (let k=0;k<40;k++){ const a=fr(i*40+k)*Math.PI*2; const rr=(0.4+fr(i*40+k+7)*0.1); g.fill(C.edge[0],C.edge[1],C.edge[2]*fr(k+i),40*fr(k*3)); g.ellipse(cx+Math.cos(a)*G.w*0.5*rr*2, G.y+Math.sin(a)*G.w*0.17, u*0.004,u*0.004); } }
  }
  g.pop();
}
image(S.bg, 0, 0);

// ---- act shaping ----
let jetGain = 1, jetSpread = 1;
if (P.act==='surge'){ jetGain = 0.5 + K.intensity*1.4; }
else if (P.act==='dance'){ jetGain = 0.7 + K.pulse*1.1; jetSpread = 1.15; }
else { jetGain = 0.9 + Math.sin(K.t*0.5)*0.12; } // calm: gentle breathe on real-time

const drive = jetGain * (0.85 + S.bass*1.3 + P.energy*0.5) * (0.6 + K.intensity*0.6);
const jetH = u*sc*0.16*drive;
const topTierY = tierGeom(tiers-1).y - u*sc*0.05;

// ---- animated water jets ----
push();
noStroke();
if (!C.noir) blendMode(C.therm?SCREEN:BLEND);
for (let j=0;j<njet;j++){
  const off = njet===1?0:((j/(njet-1))-0.5);
  const jx = cx + off*u*sc*0.05*jetSpread;
  const jw = jetSpread*u*sc*0.014;
  const hh = jetH*(0.7+0.6*(1-Math.abs(off*2)))* (0.72+0.42*Math.sin(K.t*1.7 + j*0.9));
  // rising translucent column of stacked drops
  const n = 9;
  for (let s=0;s<n;s++){ const t=s/(n-1);
    const yy = topTierY - t*hh;
    const xx = jx + Math.sin(t*3 + K.t*2 + j)*jw*1.5;
    const a = C.schem? 30*(1-t) : 55*(1-t*0.7);
    fill(C.water[0], C.water[1]*(C.ink?0.6:1), Math.min(100,C.water[2]+t*20), a);
    ellipse(xx, yy, jw*(1.6-t), jw*(2.4-t));
  }
  // foam crown at the top
  fill(C.foam[0],C.foam[1],C.foam[2], C.schem?40:70);
  ellipse(jx, topTierY-hh, jw*2.2, jw*1.6);
}

// ---- particle spray (real-time emission, ring-buffer, capped) ----
if (!S.pp){ S.pp = []; }
const CAP = Math.round(30 + P.density*110); // <=140
// emit based on real-time accumulator so motion never re-phases
S.emit = (S.emit||0) + dt*(18 + P.density*60)*(0.6+drive*0.6);
while (S.emit >= 1 && S.pp.length < CAP){ S.emit -= 1;
  const j = Math.floor(fr(K.t*97+S.pp.length)*njet);
  const off = njet===1?0:((j/(njet-1))-0.5);
  const jx = cx + off*u*sc*0.05*jetSpread;
  const ang = -Math.PI/2 + (fr(S.pp.length*3+K.t*13)-0.5)*1.1*jetSpread;
  const spd = (0.6+fr(S.pp.length*7+K.t*3)*0.7)* (jetH*0.9+u*0.02);
  S.pp.push({ x:jx, y:topTierY-jetH*0.9, vx:Math.cos(ang)*spd, vy:Math.sin(ang)*spd, life:1, sz:0.6+fr(S.pp.length)*0.8 });
}
const grav = u*sc*3.2;
for (let i=S.pp.length-1;i>=0;i--){ const p=S.pp[i];
  p.vy += grav*dt; p.x += p.vx*dt; p.y += p.vy*dt; p.life -= dt*0.5;
  // land in pool
  if (p.y > base || p.life<=0){ S.pp.splice(i,1); continue; }
  const a = C.schem? 45*p.life : 80*p.life;
  fill(C.foam[0],C.foam[1]*0.7,C.foam[2], a);
  ellipse(p.x, p.y, jw2(p.sz), jw2(p.sz));
}
function jw2(s){ return s*u*sc*0.012; }
pop();

// ---- cascading overflow curtains (wide continuous real-time flow) ----
push();
noStroke();
if (!C.noir) blendMode(C.therm?SCREEN:BLEND);
const fallH = u*sc*0.19;
for (let i=1;i<tiers;i++){
  const G = tierGeom(i);
  const rimY = G.y + G.h*0.5;
  const wSpan = G.w*0.9;
  const streaks = Math.round(11 + P.density*11);
  for (let k=0;k<streaks;k++){
    const fx = cx + (streaks===1?0:(k/(streaks-1)-0.5))*wSpan;
    const rate = 0.55 + fr(i*17+k)*0.5;
    const ph = ((K.t*rate + fr(i*31+k*7)) % 1 + 1) % 1;
    const yy = rimY + ph*fallH;
    const wob = Math.sin(K.t*2.0 + k)*u*sc*0.004;
    const a = (1-ph)*(C.schem?42:62);
    fill(C.water[0], C.water[1]*(C.ink?0.6:0.85), Math.min(100,C.water[2]+15), a);
    ellipse(fx+wob, yy, u*sc*0.013, fallH*0.55);
  }
}
blendMode(BLEND);
pop();

// ---- pool ripples (continuous real-time drift) ----
push();
noFill();
const pG = tierGeom(0);
for (let r=0;r<6;r++){
  const ph = ((K.t*0.32 + r*0.166) % 1 + 1) % 1;
  const rr = pG.w*(0.12 + ph*1.02);
  stroke(C.edge[0], C.edge[1], C.edge[2], (1-ph)*(C.schem?58:52));
  strokeWeight(Math.max(1.2,u*0.0019));
  ellipse(cx, pG.y+pG.h*0.3, rr, rr*0.34);
}
// bass-driven bright ring
if (S.bass>0.05){ stroke(C.foam[0],C.foam[1],C.foam[2], S.bass*60); ellipse(cx, pG.y+pG.h*0.3, pG.w*0.9, pG.w*0.3); }
pop();

// night-light glint on top-tier water (real-time shimmer)
push();
blendMode(C.noir?BLEND:ADD);
const gl = 0.4+0.6*(0.5+0.5*Math.sin(K.t*2.1));
fill(C.lamp[0],C.lamp[1]*0.6,C.lamp[2], 18*gl*(0.5+P.night));
ellipse(cx, topTierY, u*sc*0.06, u*sc*0.02);
pop();

blendMode(BLEND);
drawingContext.shadowBlur = 0;
